"use client";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/app/_providers/AuthProvider";
import { Button } from "@/components/ui/button";

const ROLE_LABEL = {
  student: "Student",
  company: "Company",
  admin: "Administrator",
};

export function DashboardShell({ title, subtitle, children }) {
  const { role, logout, isAuthenticated } = useAuth();
  const router = useRouter();

  const handleLogout = () => {
    logout();
    router.replace("/auth");
  };

  return (
    <div className="min-h-screen">
      <header className="border-b border-border bg-white">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
          <Link href="/" className="flex items-center gap-2 text-accent">
            <span className="text-lg font-semibold">CareerBridge AI</span>
          </Link>
          <div className="flex items-center gap-3 text-sm">
            {isAuthenticated && (
              <>
                <span className="text-muted-foreground">
                  Signed in as <strong>{ROLE_LABEL[role] || role}</strong>
                </span>
                <Button variant="outline" size="sm" onClick={handleLogout}>
                  Log out
                </Button>
              </>
            )}
          </div>
        </div>
      </header>
      <main className="mx-auto max-w-6xl px-6 py-8">
        <div className="mb-6">
          <h1 className="text-2xl font-semibold">{title}</h1>
          {subtitle && (
            <p className="mt-1 text-sm text-muted-foreground">{subtitle}</p>
          )}
        </div>
        {children}
      </main>
    </div>
  );
}
